    {
      "name": "MvPowerSeries.le_weightedOrder_mul",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R} : MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g ≤ MvPowerSeries.weightedOrder w (f * g)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.weightedOrder_mul_ge",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R} : MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g ≤ MvPowerSeries.weightedOrder w (f * g)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.weightedHomogeneousComponent_mul_of_le_weightedOrder",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] {w : σ → ℕ} {f g : MvPowerSeries σ R} {p q : ℕ} (hf : ↑p ≤ MvPowerSeries.weightedOrder w f) (hg : ↑q ≤ MvPowerSeries.weightedOrder w g) : (MvPowerSeries.weightedHomogeneousComponent w (p + q)) (f * g) = (MvPowerSeries.weightedHomogeneousComponent w p) f * (MvPowerSeries.weightedHomogeneousComponent w q) g",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.coeff_mul_left_one_sub_of_lt_weightedOrder",
      "type": " {σ : Type u_1} (w : σ → ℕ) {R : Type u_3} [Ring R] {f g : MvPowerSeries σ R} {d : σ →₀ ℕ} (h : ↑((Finsupp.weight w) d) < MvPowerSeries.weightedOrder w g) : (MvPowerSeries.coeff d) (f * (1 - g)) = (MvPowerSeries.coeff d) f",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.coeff_mul_right_one_sub_of_lt_weightedOrder",
      "type": " {σ : Type u_1} (w : σ → ℕ) {R : Type u_3} [Ring R] {f g : MvPowerSeries σ R} {d : σ →₀ ℕ} (h : ↑((Finsupp.weight w) d) < MvPowerSeries.weightedOrder w g) : (MvPowerSeries.coeff d) ((1 - g) * f) = (MvPowerSeries.coeff d) f",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.coeff_mul_prod_one_sub_of_lt_weightedOrder",
      "type": " {σ : Type u_1} (w : σ → ℕ) {R : Type u_4} {ι : Type u_5} [CommRing R] (d : σ →₀ ℕ) (s : Finset ι) (f : MvPowerSeries σ R) (g : ι → MvPowerSeries σ R) (h : ∀ i ∈ s, ↑((Finsupp.weight w) d) < MvPowerSeries.weightedOrder w (g i)) : (MvPowerSeries.coeff d) (f * ∏ i ∈ s, (1 - g i)) = (MvPowerSeries.coeff d) f",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "PowerSeries.le_weightedOrder_subst",
      "type": " {R : Type u_2} [CommRing R] {τ : Type u_3} {S : Type u_4} [CommRing S] [Algebra R S] {a : MvPowerSeries τ S} (w : τ → ℕ) (ha : PowerSeries.HasSubst a) (f : PowerSeries R) : f.order * MvPowerSeries.weightedOrder w a ≤ MvPowerSeries.weightedOrder w (PowerSeries.subst a f)",
      "module": "Mathlib.RingTheory.PowerSeries.Substitution"
    },
    {
      "name": "MvPowerSeries.weightedOrder_mul",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] [NoZeroDivisors R] (w : σ → ℕ) (f g : MvPowerSeries σ R) : MvPowerSeries.weightedOrder w (f * g) = MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g",
      "module": "Mathlib.RingTheory.MvPowerSeries.NoZeroDivisors"
    }
  ]
}
